pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value > 0);

        uint256 initialBalance = address(c).balance;
        uint256 initialDepositsCount = c.depositsCount();

        // Ensure the contract has ETH to send
        vm.deal(address(c), value);

        // Send ETH to target, which may trigger receive on target if it's a contract
        c.sendMoney(target, value);

        // After the call, check the invariant:
        // If the balance decreased by exactly value (no receive triggered), depositsCount should be unchanged
        // If the balance decreased by less than value (some ETH stuck in target due to receive), depositsCount should increase by exactly 1 for each successful receive (but here it's a simple call, so only 1 possible)
        // Since receive() increments depositsCount, and sendMoney does a simple call, the number of increments is either 0 (target is EOA) or 1 (target is a contract with receive)
        // The invariant: depositsCount >= initialDepositsCount and the difference is either 0 or 1 depending on whether the call triggered receive
        uint256 finalDepositsCount = c.depositsCount();
        uint256 balanceDiff = initialBalance - address(c).balance;

        // General rule: if the call didn't consume all value (i.e., some ETH was received by this contract via fallback), then depositsCount increased
        // Actually, the only way depositsCount increases is if this contract's receive() is called, which happens when someone sends ETH to this contract
        // sendMoney sends ETH *from* this contract to target, not to this contract, so depositsCount should never change
        // Therefore the invariant is: depositsCount remains unchanged after sendMoney
        assertTrue(finalDepositsCount == initialDepositsCount, "depositsCount should remain unchanged after sendMoney");
    }
}

