    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 count, address target, uint256 value) public {
        vm.assume(count < type(uint256).max);
        // Simulate count deposits to bring depositsCount close to overflow
        for (uint256 i = 0; i < count; i++) {
            (bool success,) = address(c).call{value: 1 wei}("");
            require(success);
        }
        uint256 before = c.depositsCount();
        // Call sendMoney to trigger receive() if target has code, else just transfer
        // The bug is triggered when depositsCount is type(uint256).max and more deposits happen
        // But we can only observe the difference after sendMoney completes.
        // The invariant: depositsCount should never be such that (depositsCount + 1) overflows
        // In the reference, require((depositsCount + 1) >= depositsCount) always holds until overflow,
        // but the buggy version allows overflow.
        // After sendMoney, depositsCount must not be type(uint256).max.
        c.sendMoney(target, value);
        assertTrue(c.depositsCount() < type(uint256).max);
    }
}

